args.sql:
ALTER TABLE patients ADD COLUMN IF NOT EXISTS review_flag text;

UPDATE patients p
SET review_flag = 'Case Review Required'
WHERE pat_key IN (
    SELECT l.pat_ref
    FROM (
        SELECT DISTINCT ON (e.pat_ref) e.pat_ref, e.ab_ref
        FROM encounters e
        ORDER BY e.pat_ref, e.time_mark DESC
    ) l
    JOIN assessmentbasics ab ON l.ab_ref = ab.ab_key
    WHERE CAST(SPLIT_PART(ab.hosp_risk_density, ' ', 1) AS numeric) > 1.5
);

